  3	import br.com.pousada.maralta.controller.*;
  4	import br.com.pousada.maralta.database.Database;
  5	import br.com.pousada.maralta.repository.*;
  6	import br.com.pousada.maralta.service.*;
  7	import com.fasterxml.jackson.databind.ObjectMapper;
  8	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  9	import io.javalin.Javalin;
 10	import io.javalin.json.JavalinJackson;
 11	
 12	public class Application {
 13	    public static void main(String[] args) {
 14	        String dbUrl = System.getenv("DB_URL");
 15	        String dbUser = System.getenv("DB_USER");
 16	        String dbPassword = System.getenv("DB_PASSWORD");
 17	        String portStr = System.getenv("PORT");
 18	
 19	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 20	            throw new IllegalStateException("DB_URL, DB_USER, and DB_PASSWORD must be set");
 21	        }
 22	
 23	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 24	
 25	        Database database = new Database(dbUrl, dbUser, dbPassword);
 26	
 27	        RoomRepository roomRepository = new RoomRepository(database);
 28	        ReservationRepository reservationRepository = new ReservationRepository(database);
 29	        MessageRepository messageRepository = new MessageRepository(database);
 30	
 31	        PricingService pricingService = new PricingService();
 32	        RoomService roomService = new RoomService(roomRepository);
 33	        MessageService messageService = new MessageService(messageRepository);
 34	        ReservationService reservationService = new ReservationService(
 35	            reservationRepository, roomService, pricingService, messageService
 36	        );
 37	        ReportService reportService = new ReportService(reservationRepository, roomService);
 38	
 39	        RoomController roomController = new RoomController(roomService);
 40	        ReservationController reservationController = new ReservationController(reservationService);
 41	        MessageController messageController = new MessageController(messageService);
 42	        ReportController reportController = new ReportController(reportService);
 43	
 44	        ObjectMapper objectMapper = new ObjectMapper();
 45	        objectMapper.registerModule(new JavaTimeModule());
 46	
 47	        Javalin app = Javalin.create(config -> {
 48	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 49	        }).start(port);
 50	
 51	        app.get("/rooms", roomController::getRooms);
 52	
 53	        app.post("/reservations", reservationController::createReservation);
 54	        app.get("/reservations/{id}", reservationController::getReservation);
 55	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 56	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 57	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 58	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 59	        app.get("/reservations/{id}/document", reservationController::getDocument);
 60	
 61	        app.get("/messages", messageController::getMessages);
 62	
 63	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 64	        app.get("/reports/revenue", reportController::getRevenueReport);
 65	
 66	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 67	            app.stop();
 68	            database.close();
 69	        }));
 70	
 71	        System.out.println("Pousada Maré Alta system started on port " + port);
 72	    }
 73	}
