118	import java.time.LocalDate;
119	import java.time.YearMonth;
120	import java.time.format.DateTimeParseException;
121	
122	public class ReportController {
123	    private final ReportService reportService;
124	
125	    public ReportController(ReportService reportService) {
126	        this.reportService = reportService;
127	    }
128	
129	    public void getOccupancyReport(Context ctx) {
130	        try {
131	            String dateStr = ctx.queryParam("date");
132	            if (dateStr == null) {
133	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
134	                return;
135	            }
136	
137	            LocalDate date;
138	            try {
139	                date = LocalDate.parse(dateStr);
140	            } catch (DateTimeParseException e) {
141	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
142	                return;
143	            }
144	
145	            String csv = reportService.generateOccupancyReport(date);
146	            ctx.contentType("text/csv; charset=utf-8");
147	            ctx.result(csv);
148	
149	        } catch (Exception e) {
150	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
151	        }
152	    }
153	
154	    public void getRevenueReport(Context ctx) {
155	        try {
156	            String monthStr = ctx.queryParam("month");
157	            if (monthStr == null) {
158	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
159	                return;
160	            }
161	
162	            YearMonth yearMonth;
163	            try {
164	                yearMonth = YearMonth.parse(monthStr);
165	            } catch (DateTimeParseException e) {
166	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
167	                return;
168	            }
169	
170	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
171	            ctx.contentType("text/csv; charset=utf-8");
172	            ctx.result(csv);
173	
174	        } catch (Exception e) {
175	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
176	        }
177	    }
178	}
179	package br.com.pousada.maralta.controller;
180	
181	import br.com.pousada.maralta.domain.*;
182	import br.com.pousada.maralta.guesttype.GuestType;
183	import br.com.pousada.maralta.guesttype.GuestTypeFactory;
184	import br.com.pousada.maralta.service.ReservationService;
185	import io.javalin.http.Context;
186	
187	import java.math.BigDecimal;
188	import java.time.LocalDate;
189	import java.time.format.DateTimeParseException;
190	import java.util.LinkedHashMap;
191	import java.util.Map;
192	
193	public class ReservationController {
194	    private final ReservationService reservationService;
195	
196	    public ReservationController(ReservationService reservationService) {
197	        this.reservationService = reservationService;
198	    }
199	
200	    public void createReservation(Context ctx) {
201	        try {
202	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
203	
204	            String roomNumber = (String) body.get("roomNumber");
205	            String guestName = (String) body.get("guestName");
206	            String guestEmail = (String) body.get("guestEmail");
207	            String checkInStr = (String) body.get("checkIn");
208	            String checkOutStr = (String) body.get("checkOut");
209	            Integer guests = getInteger(body, "guests");
210	            String ratePlanStr = (String) body.get("ratePlan");
211	
212	            if (roomNumber == null || guestName == null || guestEmail == null ||
213	                checkInStr == null || checkOutStr == null || guests == null || ratePlanStr == null) {
214	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
215	                return;
216	            }
217	
218	            GuestType guestType = GuestTypeFactory.createFromRequest(body);
219	            if (guestType == null) {
220	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid guest identification"));
221	                return;
222	            }
223	
224	            LocalDate checkIn;
225	            LocalDate checkOut;
226	            try {
227	                checkIn = LocalDate.parse(checkInStr);
228	                checkOut = LocalDate.parse(checkOutStr);
229	            } catch (DateTimeParseException e) {
230	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
231	                return;
232	            }
233	
234	            if (!checkOut.isAfter(checkIn)) {
235	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
236	                return;
237	            }
238	
239	            RatePlan ratePlan;
240	            try {
241	                ratePlan = RatePlan.valueOf(ratePlanStr);
242	            } catch (IllegalArgumentException e) {
243	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
244	                return;
245	            }
246	
247	            Reservation reservation = reservationService.createReservation(
248	                roomNumber, guestName, guestEmail, guestType,
249	                checkIn, checkOut, guests, ratePlan
250	            );
251	
252	            ctx.status(201).json(toJson(reservation));
253	
254	        } catch (ReservationService.RoomNotFoundException e) {
255	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
256	        } catch (ReservationService.InvalidRequestException e) {
257	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
258	        } catch (ReservationService.RoomUnavailableException e) {
259	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room not available"));
260	        } catch (ReservationService.CapacityExceededException e) {
261	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Guests exceed room capacity"));
262	        } catch (Exception e) {
263	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
264	        }
265	    }
266	
267	    public void getReservation(Context ctx) {
268	        try {
269	            long id = Long.parseLong(ctx.pathParam("id"));
270	            Reservation reservation = reservationService.getReservation(id);
271	            ctx.json(toJson(reservation));
272	        } catch (ReservationService.ReservationNotFoundException e) {
273	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
274	        } catch (NumberFormatException e) {
275	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
276	        }
277	    }
278	
279	    public void confirmReservation(Context ctx) {
280	        try {
281	            long id = Long.parseLong(ctx.pathParam("id"));
282	            Reservation reservation = reservationService.confirmReservation(id);
283	            ctx.json(toJson(reservation));
284	        } catch (ReservationService.ReservationNotFoundException e) {
285	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
286	        } catch (ReservationService.OperationNotAllowedException e) {
287	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed"));
288	        } catch (NumberFormatException e) {
289	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
290	        }
291	    }
292	
293	    public void cancelReservation(Context ctx) {
294	        try {
295	            long id = Long.parseLong(ctx.pathParam("id"));
296	            Reservation reservation = reservationService.cancelReservation(id);
297	            ctx.json(toJson(reservation));
298	        } catch (ReservationService.ReservationNotFoundException e) {
299	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
300	        } catch (ReservationService.OperationNotAllowedException e) {
301	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed"));
302	        } catch (NumberFormatException e) {
303	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
304	        }
305	    }
306	
307	    public void checkIn(Context ctx) {
308	        try {
309	            long id = Long.parseLong(ctx.pathParam("id"));
310	            Reservation reservation = reservationService.checkIn(id);
311	            ctx.json(toJson(reservation));
312	        } catch (ReservationService.ReservationNotFoundException e) {
313	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
314	        } catch (ReservationService.OperationNotAllowedException e) {
315	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed"));
316	        } catch (NumberFormatException e) {
317	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
318	        }
319	    }
320	
321	    public void checkOut(Context ctx) {
322	        try {
323	            long id = Long.parseLong(ctx.pathParam("id"));
324	            Document document = reservationService.checkOut(id);
325	            ctx.json(toDocumentJson(document));
326	        } catch (ReservationService.ReservationNotFoundException e) {
327	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
328	        } catch (ReservationService.OperationNotAllowedException e) {
329	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed"));
330	        } catch (NumberFormatException e) {
331	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
332	        }
333	    }
334	
335	    public void getDocument(Context ctx) {
336	        try {
337	            long id = Long.parseLong(ctx.pathParam("id"));
338	            Document document = reservationService.getDocument(id);
339	            ctx.json(toDocumentJson(document));
340	        } catch (ReservationService.ReservationNotFoundException e) {
341	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
342	        } catch (ReservationService.OperationNotAllowedException e) {
343	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed"));
344	        } catch (NumberFormatException e) {
345	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
346	        }
347	    }
348	
349	    private Map<String, Object> toJson(Reservation reservation) {
350	        Map<String, Object> json = new LinkedHashMap<>();
351	        json.put("id", reservation.getId());
352	        json.put("roomNumber", reservation.getRoomNumber());
353	        json.put("guestName", reservation.getGuestName());
354	        json.put("guestEmail", reservation.getGuestEmail());
355	        json.put("guestCpf", reservation.getGuestType().getGuestCpf());
356	        json.put("companyCnpj", reservation.getGuestType().getCompanyCnpj());
357	        json.put("companyName", reservation.getGuestType().getCompanyName());
358	        json.put("guestPassport", reservation.getGuestType().getGuestPassport());
359	        json.put("guestCountry", reservation.getGuestType().getGuestCountry());
360	        json.put("checkIn", reservation.getCheckIn().toString());
361	        json.put("checkOut", reservation.getCheckOut().toString());
362	        json.put("guests", reservation.getGuests());
363	        json.put("ratePlan", reservation.getRatePlan().name());
364	        json.put("nights", reservation.getNights());
365	        json.put("subtotal", toDouble(reservation.getSubtotal()));
366	        json.put("discount", toDouble(reservation.getDiscount()));
367	        json.put("total", toDouble(reservation.getTotal()));
368	        json.put("status", reservation.getStatus().name());
369	        json.put("amountPaid", toDouble(reservation.getAmountPaid()));
370	        json.put("refund", reservation.getRefund() != null ? toDouble(reservation.getRefund()) : null);
371	        return json;
372	    }
373	
374	    private Map<String, Object> toDocumentJson(Document document) {
375	        Map<String, Object> json = new LinkedHashMap<>();
376	        json.put("title", document.getTitle());
377	        json.put("reservationId", document.getReservationId());
378	        json.put("guestName", document.getGuestName());
379	        json.put("guestCpf", document.getGuestCpf());
380	        json.put("companyCnpj", document.getCompanyCnpj());
381	        json.put("companyName", document.getCompanyName());
382	        json.put("guestPassport", document.getGuestPassport());
383	        json.put("guestCountry", document.getGuestCountry());
384	        json.put("roomNumber", document.getRoomNumber());
385	        json.put("roomType", document.getRoomType());
386	        json.put("checkIn", document.getCheckIn().toString());
387	        json.put("checkOut", document.getCheckOut().toString());
388	        json.put("nights", document.getNights());
389	        json.put("subtotal", toDouble(document.getSubtotal()));
390	        json.put("discount", toDouble(document.getDiscount()));
391	        json.put("total", toDouble(document.getTotal()));
392	        json.put("text", document.getText());
393	        return json;
394	    }
395	
396	    private double toDouble(BigDecimal value) {
397	        return value.doubleValue();
398	    }
399	
400	    private Integer getInteger(Map<String, Object> map, String key) {
401	        Object value = map.get(key);
402	        if (value instanceof Integer) {
403	            return (Integer) value;
404	        } else if (value instanceof Number) {
405	            return ((Number) value).intValue();
406	        }
407	        return null;
408	    }
409	}
