400	    private Integer getInteger(Map<String, Object> map, String key) {
401	        Object value = map.get(key);
402	        if (value instanceof Integer) {
403	            return (Integer) value;
404	        } else if (value instanceof Number) {
405	            return ((Number) value).intValue();
406	        }
407	        return null;
408	    }
