116	public class ReportService {
117	    private final ReservationRepository reservationRepository;
118	    private final RoomService roomService;
119	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
120	
121	    public ReportService(ReservationRepository reservationRepository, RoomService roomService) {
122	        this.reservationRepository = reservationRepository;
123	        this.roomService = roomService;
124	    }
125	
126	    public String generateOccupancyReport(LocalDate date) {
127	        List<Reservation> reservations = reservationRepository.findByDate(date);
128	        List<Room> allRooms = roomService.getAllRooms();
129	
130	        StringBuilder csv = new StringBuilder();
131	        csv.append("room,type,reservation,check_in,check_out\n");
132	
133	        for (Reservation reservation : reservations) {
134	            csv.append(reservation.getRoomNumber()).append(",");
135	
136	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
137	            csv.append(room.getType().name()).append(",");
138	            csv.append(reservation.getId()).append(",");
139	            csv.append(reservation.getCheckIn().format(DATE_FORMAT)).append(",");
140	            csv.append(reservation.getCheckOut().format(DATE_FORMAT)).append("\n");
141	        }
142	
143	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
144	
145	        return csv.toString();
146	    }
147	
148	    public String generateRevenueReport(int year, int month) {
149	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
150	
151	        StringBuilder csv = new StringBuilder();
152	        csv.append("reservation,room,check_in,check_out,status,amount\n");
153	
154	        BigDecimal totalRevenue = BigDecimal.ZERO;
155	
156	        for (Reservation reservation : reservations) {
157	            BigDecimal revenue = reservation.getAmountPaid();
158	            if (reservation.getRefund() != null) {
159	                revenue = revenue.subtract(reservation.getRefund());
160	            }
161	
162	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
163	                csv.append(reservation.getId()).append(",");
164	                csv.append(reservation.getRoomNumber()).append(",");
165	                csv.append(reservation.getCheckIn().format(DATE_FORMAT)).append(",");
166	                csv.append(reservation.getCheckOut().format(DATE_FORMAT)).append(",");
167	                csv.append(reservation.getStatus().name()).append(",");
168	                csv.append(String.format(Locale.US, "%.2f", revenue)).append("\n");
169	
170	                totalRevenue = totalRevenue.add(revenue);
171	            }
172	        }
173	
174	        csv.append("total,").append(String.format(Locale.US, "%.2f", totalRevenue));
175	
176	        return csv.toString();
177	    }
178	}
