189	public class ReservationService {
190	    private final ReservationRepository reservationRepository;
191	    private final RoomService roomService;
192	    private final PricingService pricingService;
193	    private final MessageService messageService;
194	
195	    public ReservationService(
196	        ReservationRepository reservationRepository,
197	        RoomService roomService,
198	        PricingService pricingService,
199	        MessageService messageService
200	    ) {
201	        this.reservationRepository = reservationRepository;
202	        this.roomService = roomService;
203	        this.pricingService = pricingService;
204	        this.messageService = messageService;
205	    }
206	
207	    public Reservation createReservation(
208	        String roomNumber,
209	        String guestName,
210	        String guestEmail,
211	        GuestType guestType,
212	        LocalDate checkIn,
213	        LocalDate checkOut,
214	        int guests,
215	        RatePlan ratePlan
216	    ) {
217	        Room room = roomService.getRoomByNumber(roomNumber);
218	        if (room == null) {
219	            throw new RoomNotFoundException();
220	        }
221	
222	        if (guests < 1) {
223	            throw new InvalidRequestException();
224	        }
225	
226	        if (guests > room.getCapacity()) {
227	            throw new CapacityExceededException();
228	        }
229	
230	        var conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
231	        if (!conflicts.isEmpty()) {
232	            throw new RoomUnavailableException();
233	        }
234	
235	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
236	        BigDecimal subtotal = pricingService.calculateSubtotal(checkIn, checkOut, room.getType());
237	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
238	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
239	
240	        Reservation reservation = new Reservation(
241	            0,
242	            roomNumber,
243	            guestName,
244	            guestEmail,
245	            guestType,
246	            checkIn,
247	            checkOut,
248	            guests,
249	            ratePlan,
250	            nights,
251	            subtotal,
252	            discount,
253	            total,
254	            ReservationStatus.PENDING,
255	            BigDecimal.ZERO,
256	            null
257	        );
258	
259	        return reservationRepository.save(reservation);
260	    }
261	
262	    public Reservation getReservation(long id) {
263	        Reservation reservation = reservationRepository.findById(id);
264	        if (reservation == null) {
265	            throw new ReservationNotFoundException();
266	        }
267	        return reservation;
268	    }
