270	    public Reservation confirmReservation(long id) {
271	        Reservation reservation = getReservation(id);
272	
273	        if (!reservation.canConfirm()) {
274	            throw new OperationNotAllowedException();
275	        }
276	
277	        reservation.setStatus(ReservationStatus.CONFIRMED);
278	        reservation.setAmountPaid(reservation.getTotal());
279	        reservationRepository.update(reservation);
280	
281	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
282	        Document document = reservation.getGuestType().generateDocument(
283	            reservation.getId(),
284	            reservation.getGuestName(),
285	            reservation.getRoomNumber(),
286	            room.getType().name(),
287	            reservation.getCheckIn(),
288	            reservation.getCheckOut(),
289	            reservation.getNights(),
290	            reservation.getSubtotal(),
291	            reservation.getDiscount(),
292	            reservation.getTotal()
293	        );
294	
295	        messageService.sendConfirmationEmail(reservation.getGuestName(), reservation.getGuestEmail(), document);
296	
297	        return reservation;
298	    }
299	
300	    public Reservation cancelReservation(long id) {
301	        Reservation reservation = getReservation(id);
302	
303	        if (!reservation.canCancel()) {
304	            throw new OperationNotAllowedException();
305	        }
306	
307	        reservation.setStatus(ReservationStatus.CANCELLED);
308	
309	        BigDecimal refundAmount = BigDecimal.ZERO;
310	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
311	            refundAmount = reservation.getAmountPaid();
312	        }
313	
314	        reservation.setRefund(refundAmount);
315	        reservationRepository.update(reservation);
316	
