 37	package br.com.pousada.maralta.service;
 38	
 39	import br.com.pousada.maralta.domain.RatePlan;
 40	import br.com.pousada.maralta.domain.RoomType;
 41	
 42	import java.math.BigDecimal;
 43	import java.math.RoundingMode;
 44	import java.time.LocalDate;
 45	import java.time.Month;
 46	
 47	public class PricingService {
 48	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 49	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 50	
 51	    public BigDecimal calculateNightPrice(LocalDate date, RoomType roomType) {
 52	        BigDecimal baseRate = BigDecimal.valueOf(roomType.getBaseRate());
 53	
 54	        if (isHighSeason(date)) {
 55	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
 56	        }
 57	
 58	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
 59	    }
 60	
 61	    public BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut, RoomType roomType) {
 62	        BigDecimal subtotal = BigDecimal.ZERO;
 63	        LocalDate current = checkIn;
 64	
 65	        while (current.isBefore(checkOut)) {
 66	            BigDecimal nightPrice = calculateNightPrice(current, roomType);
 67	            subtotal = subtotal.add(nightPrice);
 68	            current = current.plusDays(1);
 69	        }
 70	
 71	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
 72	    }
 73	
 74	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
 75	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
 76	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
 77	        }
 78	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 79	    }
 80	
 81	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 82	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 83	    }
 84	
 85	    private boolean isHighSeason(LocalDate date) {
 86	        Month month = date.getMonth();
 87	        int day = date.getDayOfMonth();
 88	
 89	        if (month == Month.JULY) {
 90	            return true;
 91	        }
 92	
 93	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
 94	            return true;
 95	        }
 96	
 97	        if (month == Month.DECEMBER && day >= 15) {
 98	            return true;
 99	        }
100	
101	        return false;
102	    }
103	}
