640	public final class GuestTypeFactory {
641	
642	    public static GuestType createFromRequest(Map<String, Object> fields) {
643	        String cpf = (String) fields.get("guestCpf");
644	        String cnpj = (String) fields.get("companyCnpj");
645	        String companyName = (String) fields.get("companyName");
646	        String passport = (String) fields.get("guestPassport");
647	        String country = (String) fields.get("guestCountry");
648	
649	        int providedFields = 0;
650	        if (cpf != null) providedFields++;
651	        if (cnpj != null && companyName != null) providedFields++;
652	        if (passport != null && country != null) providedFields++;
653	
654	        if (providedFields != 1) {
655	            return null;
656	        }
657	
658	        if (cpf != null) {
659	            return new IndividualGuest(cpf);
660	        }
661	
662	        if (cnpj != null && companyName != null) {
663	            return new CorporateGuest(cnpj, companyName);
664	        }
665	
666	        if (passport != null && country != null) {
667	            return new ForeignGuest(passport, country);
668	        }
669	
670	        return null;
671	    }
672	
673	    public static GuestType createFromDatabase(
674	        String cpf,
675	        String cnpj,
676	        String companyName,
677	        String passport,
678	        String country
679	    ) {
680	        if (cpf != null) {
681	            return new IndividualGuest(cpf);
682	        }
683	
684	        if (cnpj != null) {
685	            return new CorporateGuest(cnpj, companyName);
686	        }
687	
688	        if (passport != null) {
689	            return new ForeignGuest(passport, country);
690	        }
691	
692	        throw new IllegalStateException("Invalid guest type data");
693	    }
694	}
