 11	public class Database {
 12	    private final HikariDataSource dataSource;
 13	
 14	    public Database(String jdbcUrl, String username, String password) {
 15	        HikariConfig config = new HikariConfig();
 16	        config.setJdbcUrl(jdbcUrl);
 17	        config.setUsername(username);
 18	        config.setPassword(password);
 19	        config.setMaximumPoolSize(10);
 20	
 21	        this.dataSource = new HikariDataSource(config);
 22	        runMigrations();
 23	    }
 24	
 25	    public Connection getConnection() throws SQLException {
 26	        return dataSource.getConnection();
 27	    }
 28	
 29	    public DataSource getDataSource() {
 30	        return dataSource;
 31	    }
 32	
 33	    public void close() {
 34	        dataSource.close();
 35	    }
 36	
 37	    private void runMigrations() {
 38	        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
 39	
 40	            stmt.execute("""
 41	                CREATE TABLE IF NOT EXISTS rooms (
 42	                    number VARCHAR(10) PRIMARY KEY,
 43	                    type VARCHAR(20) NOT NULL
 44	                )
 45	            """);
 46	
 47	            stmt.execute("""
 48	                CREATE TABLE IF NOT EXISTS reservations (
 49	                    id BIGSERIAL PRIMARY KEY,
 50	                    room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
 51	                    guest_name VARCHAR(200) NOT NULL,
 52	                    guest_email VARCHAR(200) NOT NULL,
 53	                    guest_cpf VARCHAR(14),
 54	                    company_cnpj VARCHAR(18),
 55	                    company_name VARCHAR(200),
 56	                    guest_passport VARCHAR(50),
 57	                    guest_country VARCHAR(100),
 58	                    check_in DATE NOT NULL,
 59	                    check_out DATE NOT NULL,
 60	                    guests INT NOT NULL,
 61	                    rate_plan VARCHAR(20) NOT NULL,
 62	                    nights INT NOT NULL,
 63	                    subtotal DECIMAL(10, 2) NOT NULL,
 64	                    discount DECIMAL(10, 2) NOT NULL,
 65	                    total DECIMAL(10, 2) NOT NULL,
 66	                    status VARCHAR(20) NOT NULL,
 67	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 68	                    refund DECIMAL(10, 2)
 69	                )
 70	            """);
 71	
 72	            stmt.execute("""
 73	                CREATE TABLE IF NOT EXISTS messages (
 74	                    id BIGSERIAL PRIMARY KEY,
 75	                    channel VARCHAR(20) NOT NULL,
 76	                    recipient VARCHAR(200) NOT NULL,
 77	                    subject VARCHAR(500) NOT NULL,
 78	                    body TEXT NOT NULL
 79	                )
 80	            """);
 81	
 82	            try (var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms")) {
 83	                rs.next();
 84	                if (rs.getInt(1) == 0) {
 85	                    stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
 86	                    stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
