 89	                    stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
 90	                }
 91	            }
 92	        } catch (SQLException e) {
 93	            throw new RuntimeException("Failed to run migrations", e);
 94	        }
 95	    }
