105	
106	public class MessageRepository {
107	    private final Database database;
108	
109	    public MessageRepository(Database database) {
110	        this.database = database;
111	    }
112	
113	    public Message save(String channel, String recipient, String subject, String body) {
114	        try (var conn = database.getConnection();
115	             var stmt = conn.prepareStatement(
116	                 "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id",
117	                 java.sql.Statement.RETURN_GENERATED_KEYS)) {
118	
119	            stmt.setString(1, channel);
120	            stmt.setString(2, recipient);
121	            stmt.setString(3, subject);
122	            stmt.setString(4, body);
123	
124	            var rs = stmt.executeQuery();
125	            if (rs.next()) {
126	                long id = rs.getLong(1);
127	                return new Message(id, channel, recipient, subject, body);
128	            }
129	
130	            throw new RuntimeException("Failed to get generated key");
131	        } catch (SQLException e) {
132	            throw new RuntimeException("Failed to save message", e);
133	        }
134	    }
135	
136	    public List<Message> findAll() {
137	        List<Message> messages = new ArrayList<>();
138	
139	        try (var conn = database.getConnection();
140	             var stmt = conn.prepareStatement("SELECT id, channel, recipient, subject, body FROM messages ORDER BY id")) {
141	
142	            var rs = stmt.executeQuery();
143	            while (rs.next()) {
144	                messages.add(new Message(
145	                    rs.getLong("id"),
146	                    rs.getString("channel"),
147	                    rs.getString("recipient"),
148	                    rs.getString("subject"),
149	                    rs.getString("body")
150	                ));
151	            }
