320	            var rs = stmt.executeQuery();
321	            while (rs.next()) {
322	                reservations.add(mapReservation(rs));
323	            }
324	        } catch (SQLException e) {
325	            throw new RuntimeException("Failed to fetch conflicting reservations", e);
326	        }
327	
328	        return reservations;
329	    }
