331	    public List<Reservation> findByDate(LocalDate date) {
332	        List<Reservation> reservations = new ArrayList<>();
333	
334	        try (var conn = database.getConnection();
335	             var stmt = conn.prepareStatement("""
336	                 SELECT id, room_number, guest_name, guest_email,
337	                        guest_cpf, company_cnpj, company_name, guest_passport, guest_country,
338	                        check_in, check_out, guests, rate_plan,
339	                        nights, subtotal, discount, total, status, amount_paid, refund
340	                 FROM reservations
341	                 WHERE check_in <= ? AND check_out > ? AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
342	                 ORDER BY room_number
343	             """)) {
344	
345	            stmt.setDate(1, Date.valueOf(date));
346	            stmt.setDate(2, Date.valueOf(date));
347	
348	            var rs = stmt.executeQuery();
349	            while (rs.next()) {
350	                reservations.add(mapReservation(rs));
351	            }
352	        } catch (SQLException e) {
353	            throw new RuntimeException("Failed to fetch reservations by date", e);
354	        }
355	
356	        return reservations;
357	    }
