359	    public List<Reservation> findByMonth(int year, int month) {
360	        List<Reservation> reservations = new ArrayList<>();
361	
362	        LocalDate monthStart = LocalDate.of(year, month, 1);
363	        LocalDate monthEnd = monthStart.plusMonths(1);
364	
365	        try (var conn = database.getConnection();
366	             var stmt = conn.prepareStatement("""
367	                 SELECT id, room_number, guest_name, guest_email,
368	                        guest_cpf, company_cnpj, company_name, guest_passport, guest_country,
369	                        check_in, check_out, guests, rate_plan,
370	                        nights, subtotal, discount, total, status, amount_paid, refund
371	                 FROM reservations
372	                 WHERE check_in >= ? AND check_in < ?
373	                 ORDER BY check_in, id
374	             """)) {
375	
376	            stmt.setDate(1, Date.valueOf(monthStart));
377	            stmt.setDate(2, Date.valueOf(monthEnd));
378	
379	            var rs = stmt.executeQuery();
380	            while (rs.next()) {
381	                reservations.add(mapReservation(rs));
382	            }
383	        } catch (SQLException e) {
384	            throw new RuntimeException("Failed to fetch reservations by month", e);
385	        }
386	
387	        return reservations;
