390	    private Reservation mapReservation(java.sql.ResultSet rs) throws SQLException {
391	        GuestType guestType = GuestTypeFactory.createFromDatabase(
392	            rs.getString("guest_cpf"),
393	            rs.getString("company_cnpj"),
394	            rs.getString("company_name"),
395	            rs.getString("guest_passport"),
396	            rs.getString("guest_country")
397	        );
398	
399	        BigDecimal refund = rs.getBigDecimal("refund");
400	
